(function(){
  const t = window.__fullText;
  const re = /=== (USER|ASSISTANT) ===\n/g;
  let m, marks = [];
  while ((m = re.exec(t)) !== null) {
    marks.push({role: m[1], idx: m.index, contentStart: m.index + m[0].length});
  }
  let msgs = [];
  for (let i=0;i<marks.length;i++){
    const start = marks[i].contentStart;
    const end = (i+1<marks.length) ? marks[i+1].idx : t.length;
    msgs.push({i, role: marks[i].role, start, end, len: end-start});
  }
  window.__msgIndex = msgs;
  return JSON.stringify({count: msgs.length, totalLen: t.length});
})()

